{
  "id": "r:17d4b63b7a333a81:t2:s:scene",
  "title": "山风与石",
  "location": "青石村后山林",
  "entities": [
    {
      "id": "r:17d4b63b7a333a81:t1:e:place_qingshi_village",
      "name": "青石村",
      "kind": "place"
    },
    {
      "id": "r:17d4b63b7a333a81:t1:e:person_lao_wang",
      "name": "老王",
      "kind": "person"
    },
    {
      "id": "r:17d4b63b7a333a81:t1:e:person_ling_shang",
      "name": "林商",
      "kind": "person"
    }
  ],
  "blocks": [
    {
      "kind": "narration",
      "text": "九十个日夜的风霜在青石村后的山林里留下了痕迹。云归在枯叶与乱石间摸索，指尖终于触到一块微凉的石头。那石头表面有细微的纹路，像是被某种力量打磨过，入手沉重，隐隐有温热感。"
    },
    {
      "kind": "dialogue",
      "text": "“这石头……不像普通的山石。”",
      "speaker": "self"
    },
    {
      "kind": "narration",
      "text": "云归将石头收入怀中，继续在山林中搜寻。行粮已经所剩无几，必须尽快找到补给或离开这片山林。"
    }
  ],
  "choices": [
    {
      "id": "r:17d4b63b7a333a81:t2:c:a",
      "label": "返回青石村，向老王询问石头的来历",
      "intent": "negotiate",
      "targetId": "r:17d4b63b7a333a81:t1:e:person_lao_wang",
      "stake": "low",
      "approach": "cooperate"
    },
    {
      "id": "r:17d4b63b7a333a81:t2:c:b",
      "label": "继续在山林中搜寻行粮",
      "intent": "explore",
      "targetId": "supplies",
      "stake": "high",
      "approach": "cautious"
    },
    {
      "id": "r:17d4b63b7a333a81:t2:c:c",
      "label": "返回青石村，寻找林商搭车前往云州城",
      "intent": "negotiate",
      "targetId": "r:17d4b63b7a333a81:t1:e:person_ling_shang",
      "stake": "low",
      "approach": "cooperate"
    }
  ],
  "memoryDeltas": [
    {
      "entityId": "r:17d4b63b7a333a81:t1:e:place_qingshi_village",
      "text": "云归在青石村后山林中发现了一块疑似灵石的石头。"
    ,
      "kind": "fact"
    }
  ]
}
